function compareLists(a, b) {
  if (a.length !== b.length) return a.length - b.length;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return a[i] - b[i];
  }
  return 0;
}

function enumerateCounts(values, target, index, counts, out) {
  if (index === values.length) {
    let sum = 0;
    for (let i = 0; i < values.length; i++) sum += values[i] * counts[i];
    if (sum !== target) return;
    const combo = [];
    for (let i = 0; i < values.length; i++) {
      for (let k = 0; k < counts[i]; k++) combo.push(values[i]);
    }
    out.push(combo);
    return;
  }
  const most = Math.floor(target / values[index]);
  for (let c = 0; c <= most; c++) {
    counts[index] = c;
    enumerateCounts(values, target, index + 1, counts, out);
  }
  counts[index] = 0;
}

function combinationSum(candidates, target) {
  const values = candidates.slice().sort((a, b) => a - b);
  const out = [];
  enumerateCounts(values, target, 0, new Array(values.length).fill(0), out);
  out.sort(compareLists);
  return out;
}

