def combination_sum(candidates, target):
    values = sorted(candidates)
    out = []

    def walk(index, counts):
        if index == len(values):
            total = sum(v * c for v, c in zip(values, counts))
            if total == target:
                combo = []
                for v, c in zip(values, counts):
                    combo.extend([v] * c)
                out.append(combo)
            return
        most = target // values[index]
        for c in range(most + 1):
            walk(index + 1, counts + [c])

    walk(0, [])
    out.sort(key=lambda s: (len(s), s))
    return out

