function buildCombinations(values, start, remaining, path, out) {
  if (remaining === 0) {
    out.push(path.slice());
    return;
  }
  for (let i = start; i < values.length; i++) {
    if (values[i] > remaining) break;
    path.push(values[i]);
    buildCombinations(values, i, remaining - values[i], path, out);
    path.pop();
  }
}

function combinationSum(candidates, target) {
  const values = candidates.slice().sort((a, b) => a - b);
  const out = [];
  buildCombinations(values, 0, target, [], out);
  out.sort(compareLists);
  return out;
}

