def combination_sum(candidates, target):
    values = sorted(candidates)
    reachable = {0: [[]]}
    for total in range(1, target + 1):
        found = []
        for value in values:
            if value > total:
                break
            for combo in reachable.get(total - value, []):
                if combo and combo[-1] > value:
                    continue
                found.append(combo + [value])
        reachable[total] = found
    out = [list(c) for c in reachable.get(target, [])]
    out.sort(key=lambda s: (len(s), s))
    return out

