function walkKeypad(digits, keypad, index, buffer, out) {
  if (index === digits.length) {
    out.push(buffer.join(""));
    return;
  }
  for (const letter of keypad[digits[index]]) {
    buffer.push(letter);
    walkKeypad(digits, keypad, index + 1, buffer, out);
    buffer.pop();
  }
}

